	"\"Full-day holiday\" or \"Half-day holiday\" determines how the day is counted: a full-day holiday is not a working day, a half-day holiday counts as half a day (e.g. 0.5 vacation day)." : "“全天假日”或“半天假日”决定当天如何计算：全天假日不是工作日，半天假日按半天计算（如 0.5 个年假日）。",
	"\"Scope\" distinguishes between statutory holidays, organization-wide company holidays, and custom entries. Statutory holidays are always treated as full-day holidays." : "“范围”区分法定假日、全公司假日和自定义条目。法定假日始终按全天假日处理。",
	"\"Statutory\", \"Company holiday\" or \"custom\" determines where the entry comes from and whom it applies to: statutory holidays come from the official calendar of the region, company holidays apply organisation-wide, custom entries are your own individual days. Statutory holidays are usually full-day; in Switzerland some statutory days (e.g. Sechseläuten) are half-day and count as 0.5." : "“法定”“公司假日”或“自定义”决定条目来源和适用对象：法定假日来自该地区官方日历，公司假日全组织适用，自定义条目是您自己的个别日期。法定假日通常是全天；在瑞士部分法定日（如 Sechseläuten）为半天，按 0.5 计。",
	"\"Valid to\" must be after \"Valid from\"." : "“生效至”必须晚于“生效自”。",
