	"A license key is stored, but this server cannot verify its signature with the vendor public key. Mobile and Terminal apps will reject the license until the key was signed with the matching vendor signing key. Re-apply a correctly signed license, or contact support if this persists after an app update." : "已存许可证密钥，但此服务器无法用供应商公钥验证其签名。在密钥由匹配的供应商签名密钥签发前，移动端和终端应用将拒绝该许可证。请重新应用正确签名的许可证，或在应用更新后问题仍存在时联系支持。",
