	"Another PIN or badge change is still finishing. Wait a few seconds, then try again. If a badge scan is stuck, click “Cancel scan” — that always clears it." : "另一个 PIN 或工牌变更仍在收尾。请等几秒后重试。如工牌扫描卡住，点击“取消扫描”——总会清除。",
