	"Create a new working time model, e.g., full-time (8 hours\/day) or part-time (4 hours\/day)." : "创建新工时模式，如全职（8 小时\/天）或兼职（4 小时\/天）。",
	"Create a new working time model. Define the standard working hours and rules for this model." : "创建新工时模式。定义该模式的标准工时和规则。",
