	"Dedicated app administrators appear in the list together with Nextcloud admins. Use search to find colleagues, then tick them. After saving they can open Administration (and Manager) without Nextcloud admin rights. You cannot remove your own last app-admin seat — ask a Nextcloud admin if you need to step down." : "专属应用管理员与 Nextcloud 管理员一起出现在列表中。用搜索找到同事并勾选。保存后他们无需 Nextcloud 管理权限即可打开“管理”（和“主管”）。您不能移除自己最后一个应用管理员席位——如需退出请找 Nextcloud 管理员。",
	"Dedicated app administrators appear in the list together with Nextcloud admins. Use search to find colleagues, then tick them. Changes take effect immediately after saving." : "专属应用管理员与 Nextcloud 管理员一起出现在列表中。用搜索找到同事并勾选。更改保存后立即生效。",
	"Deductions (subtract days)" : "扣减（减去天数）",
	"Default" : "默认",
	"Default daily working hours. Used for new employees until individual models are set." : "默认每日工时。在设置个人模式前用于新员工。",
	"Default daily working hours. Used for new employees until individual models are set. Decimal hours are allowed (e.g. 7.7)." : "默认每日工时。在设置个人模式前用于新员工。允许小数工时（如 7.7）。",
	"Default daily working hours. Used for new employees until individual models are set. Decimal hours are allowed (e.g. 7.74)." : "默认每日工时。在设置个人模式前用于新员工。允许小数工时（如 7.74）。",
	"Default fallback" : "默认兜底",
	"Default federal state for holidays" : "假日默认联邦州",
	"Default federal state was saved." : "默认联邦州已保存。",
	"Default is the next day that is not yet closed. Backdating requires an explicit choice." : "默认为尚未结算的下一日。补录需要明确选择。",
	"Default overlap: highest single percentage. Night window is editable. Templates are starters — not a legal guarantee." : "默认重叠：最高单一百分比。夜间时段可编辑。模板只是起点——不构成法律保证。",
	"Default paid break time" : "默认带薪休息时间",
	"Default paid break time per day (minutes)" : "默认每日带薪休息时间（分钟）",
	"Default policy created." : "默认策略已创建。",
	"Default region for public holidays" : "法定假日默认地区",
	"Default region was saved." : "默认地区已保存。",
	"Default work location" : "默认工作地点",
	"Default working hours must be between 1 and 24" : "默认工时须在 1 至 24 之间",
	"Defaults attached to a working time model (e.g. “30 hours \/ week”). Apply automatically to every employee with that model who has no individual or team rule." : "附加到工时模式的默认值（如“每周 30 小时”）。自动适用于该模式下无个人或团队规则的每位员工。",
	"Defaults to today. Pick a past or future date to see how the entitlement changes." : "默认为今天。选择过去或未来日期可查看额度如何变化。",
	"Define additional absence types for your organisation" : "为贵组织定义其他请假类型",
	"Define additional leave entitlements and their quotas" : "定义其他休假额度及其配额",
	"Define equivalent thresholds for undertime (negative balance)." : "为负工时（负余额）定义相应的阈值。",
	"Define for which absence types a substitute must be chosen before a request can be submitted." : "定义哪些请假类型在提交申请前必须选择代班人。",
	"Define how ArbeitszeitCheck validates bookings, handles break edge cases, and enforces legal limits." : "定义 ArbeitszeitCheck 如何校验打卡、处理休息边界情况并执行法定限制。",
	"Define how business trips count towards the time account" : "定义出差如何计入工时账户",
	"Define how many vacation days an employee is entitled to. Rules are evaluated top-down: a higher layer always wins. This page lets you see, edit, and simulate the full precedence chain." : "定义员工应得的年假天数。规则自上而下评估：更高层级始终优先。本页可查看、编辑并模拟完整优先级链。",
	"Define how many vacation days an employee is entitled to. Rules are evaluated top-down: a higher layer always wins. Use this page to view, edit, and simulate the full precedence chain." : "定义员工应得的年假天数。规则自上而下评估：更高层级始终优先。本页用于查看、编辑并模拟完整优先级链。",
	"Define how many vacation days people get. A higher layer always wins. Edit organisation, model, and team defaults here; simulate any person." : "定义员工获得多少年假。较高层级始终优先。在此编辑组织、模式和团队默认值；可模拟任何人。",
	"Define organisation-wide break rules here. Statutory minimum breaks always apply — these rules can only tighten them, never weaken them." : "在此定义全组织的休息规则。法定最低休息始终适用——这些规则只能加严，不能放宽。",
	"Define organizational units, assign members, and designate managers for approvals." : "定义组织单元、分配成员并指定审批主管。",
	"Define teams and assign members and managers. Managers can approve absences and time corrections for their team members. When enabled below, this replaces Nextcloud group-based manager resolution." : "定义团队并分配成员和主管。主管可批准其团队成员的请假和工时更正。启用下方选项后，这将取代基于 Nextcloud 群组的主管解析。",
	"Define teams, departments, or any organizational units in a flexible hierarchy. Assign members and managers. When enabled below, managers can approve absences and time corrections for their unit members." : "在灵活的层级中定义团队、部门或任何组织单元。分配成员和主管。启用下方选项后，主管可批准其单元成员的请假和工时更正。",
	"Define teams, departments, or other organizational units in a flexible hierarchy. Assign members and managers. If enabled below, managers can approve absences and time corrections for their units." : "在灵活的层级中定义团队、部门或其他组织单元。分配成员和主管。启用下方选项后，主管可批准其单元的请假和工时更正。",
	"Define when overtime changes from green to yellow and yellow to red (hours)." : "定义加班从绿变黄、从黄变红的阈值（小时）。",
