	"Deletes eligible time entries older than the configured retention period and clears your personal settings. Recent time entries, absences, audit logs, and compliance records are kept where the law requires it. This cannot be undone." : "删除超过所配置保留期限的可删工时记录，并清除您的个人设置。法律要求保留的近期工时记录、请假、审计日志和合规记录会保留。此操作无法撤销。",
	"Deleting this unit will unassign all members and managers from it. Sub-teams must be handled separately." : "删除此单元将解除其中所有成员和主管的分配。子团队须单独处理。",
	"Deleting this unit will unassign all members and managers." : "删除此单元将解除所有成员和主管的分配。",
