	"Download a DATEV text file for the same start and end dates as above. Hour premiums appear as extra Lohnart lines only when mapped in Global settings." : "下载与上方相同起止日期的 DATEV 文本文件。只有在全局设置中映射后，工时津贴才会以额外工资类型行显示。",
	"Download all settings, catalogues and business data as one encrypted file — then import it on your production instance." : "将所有设置、目录和业务数据下载为一个加密文件——然后在生产实例上导入。",
