	"Downloads the currently filtered list as a PDF. Without a filter, the last 30 days are exported." : "将当前筛选列表下载为 PDF。未筛选时导出最近 30 天。",
	"Downloads the last 30 days as CSV (long layout): each row shows start and end times; overnight shifts appear as two rows when your administrator enables midnight split. Use Reports for date range and optional wide layout." : "下载最近 30 天为 CSV（长布局）：每行显示起止时间；管理员启用午夜拆分时跨夜班显示为两行。日期范围和可选宽布局请用“报表”。",
