	"Each break must have both a start and end time, or leave the row empty." : "每段休息须同时有开始和结束时间，或将该行留空。",
	"Each bulk item must be an object with type and id." : "每个批量项目须为含 type 和 id 的对象。",
	"Each card below is one topic. Use the links above to jump, then save at the bottom." : "下方每张卡片是一个主题。用上方链接跳转，然后在底部保存。",
	"Each event title shows the employee name and absence type (for example “Alex – Vacation”). After changing language or scope, generate a new link and update your calendar subscription." : "每个事件标题显示员工姓名和请假类型（如“Alex – 年假”）。更改语言或范围后，请生成新链接并更新日历订阅。",
	"Each presence time needs a day, a start and an end." : "每个出勤时间需要日期、开始和结束。",
	"Each refresh covers approved absences from the last 3 months through the next 12 months. Subscribe once — the window moves forward automatically." : "每次刷新涵盖前 3 个月至后 12 个月的已批准请假。订阅一次——窗口自动前移。",
	"Each refresh includes approved absences from the last 3 months through the next 12 months. The window moves forward automatically — subscribe once." : "每次刷新包含前 3 个月至后 12 个月的已批准请假。窗口自动前移——订阅一次即可。",
	"Each row is one recorded change. Newest entries appear first." : "每行是一条已记录的更改。最新条目在前。",
	"Each rule set decides how much of a business trip counts for the time account. Active versions are frozen — changes create a new draft version." : "每套规则集决定出差计入工时账户的比例。已激活版本被冻结——更改会创建新草稿版本。",
	"Each scope (All employees or one team) can have one active link. Generating or rotating replaces the previous URL immediately — calendar apps using the old link stop updating." : "每个范围（全部员工或一个团队）可有一个活跃链接。生成或轮换会立即替换旧 URL——使用旧链接的日历应用停止更新。",
	"Each scope and calendar language has its own link. Links are stored encrypted on this server so you can copy them again later. Rotating a link invalidates the previous URL immediately." : "每个范围和日历语言各有自己的链接。链接在此服务器上加密存储，以后可再复制。轮换链接会立即作废旧 URL。",
	"Each trip day is measured by" : "每个差旅日按以下计量：",
	"Each work day needs a start and an end that is later than the start." : "每个工作日需要开始和晚于开始的结束时间。",
