	"Employees add completed work blocks by date and time. The punch clock is hidden for everyone." : "员工按日期和时间添加已完成的工作块。打卡钟对所有人隐藏。",
	"Employees and work schedules" : "员工与工作计划",
	"Employees can accumulate overtime up to a maximum (bank). Hours above the cap can be paid out at month end via Admin → Overtime payouts." : "员工加班可累积至上限（账户）。超出上限的工时可在月末通过 管理 → 加班支付 支付。",
	"Employees can clock in\/out on the dashboard and add manual time entries." : "员工可在仪表板打卡并添加手动工时记录。",
