	"Employees must use the punch clock. Manual time entries are hidden for everyone." : "员工必须使用打卡钟。手动工时记录对所有人隐藏。",
	"Employees seal a calendar month when work is complete. Administrators can reopen a sealed month if corrections are needed." : "员工在工作完成后封存日历月。如需更正，管理员可重新打开已封存月份。",
	"Employees see these types next to the built-in ones when they request an absence. Deleting a type that is still in use only disables it, so existing records keep working." : "员工申请请假时会在内置类型旁看到这些类型。删除仍在使用的类型只会停用它，现有记录不受影响。",
	"Employees who reached overtime or undertime thresholds, or whose overtime bank needs attention." : "达到加班或负工时阈值，或加班账户需要关注的员工。",
