	"Enter a name for this work schedule (e.g., \"Full-Time\", \"Part-Time\")" : "请为此工作计划输入名称（如“全职”“兼职”）",
	"Enter a number between 0 and 366 with up to two decimal places (for example 25, 25.5, 27.75, or 31.2). Comma or dot both work." : "请输入 0 至 366 之间最多两位小数的数字（如 25、25.5、27.75 或 31.2）。逗号或点均可。",
	"Enter a terminal label" : "请输入终端标签",
	"Enter a unit count and minutes per unit (e.g. 27 and 45)." : "请输入单元数和每单元分钟数（如 27 和 45）。",
	"Enter a user id." : "请输入用户 ID。",
	"Enter a valid date range." : "请输入有效的日期范围。",
	"Enter a valid number of vacation days." : "请输入有效的年假天数。",
	"Enter a value between 0 and 366 days." : "请输入 0 至 366 天之间的值。",
	"Enter absence minutes between 0 and 1440." : "请输入 0 至 1440 之间的请假分钟数。",
	"Enter annual vacation in days — the same numbers you already know (e.g. 25). Booking and remaining balances use hours; we convert using your hours-per-day factor. A higher layer always wins." : "按天输入年假——就是您已熟悉的数字（如 25）。预订和剩余余额按小时计算；我们用您的每天小时数系数换算。更高层级始终优先。",
	"Enter annual vacation in days — the same numbers you already know (e.g. 25). Booking and remaining balances use hours; we convert using your hours-per-day factor. Rules are evaluated top-down: a higher layer always wins." : "按天输入年假——就是您已熟悉的数字（如 25）。预订和剩余余额按小时计算；我们用您的每天小时数系数换算。规则自上而下评估：更高层级始终优先。",
	"Enter both break start and break end, or leave both empty." : "请同时填写休息开始和结束，或两者都留空。",
	"Enter days as usual (e.g. 25). We convert to hours automatically — no calculator needed." : "照常输入天数（如 25）。我们自动换算成小时——无需手动计算。",
	"Enter reason for declining..." : "请输入婉拒原因…",
	"Enter reason for rejection..." : "请输入拒绝原因…",
	"Enter the annual vacation days (e.g. 30 or 24.5)." : "请输入年度年假天数（如 30 或 24.5）。",
	"Enter the date and times as they should be recorded." : "请按应记录的内容输入日期和时间。",
	"Enter the weekly units and minutes per unit — the weekly hours above are filled in automatically." : "请输入每周单元数和每单元分钟数——上方每周工时会自动填充。",
	"Enter this code on the tablet within 10 minutes. It is shown only once." : "请在 10 分钟内在平板上输入此码。它只显示一次。",
	"Enter vacation days as usual (e.g. 25). We convert to hours automatically using %s hours per day — no calculator needed." : "照常输入年假天数（如 25）。我们按每天 %s 小时自动换算——无需手动计算。",
	"Enter your working times including breaks. The system will automatically check compliance with German labor law (ArbZG)." : "输入您的工时（含休息）。系统会自动检查是否符合德国劳动法（ArbZG）。",
