	"Exact days" : "精确天数",
	"Example for CSV\/JSON long layout: row 1 has date = first calendar day, start_time 22:00:00, end_time 23:59:59; row 2 has date = next day, start_time 00:00:00, end_time 06:00:00. Column working_hours is the work time share per segment (the segments sum to the full entry). This is not an extra \"break\" row — rest breaks remain tied to the original booking; split rows may show empty break columns." : "CSV\/JSON 长布局示例：第 1 行 date=第一个日历日，start_time 22:00:00，end_time 23:59:59；第 2 行 date=次日，start_time 00:00:00，end_time 06:00:00。working_hours 列为每时段的工时份额（各时段合计为完整记录）。这不是额外的“休息”行——休息仍归属原始记录；拆分行的休息列可能为空。",
	"Example: 30 or 24.5 days per year" : "示例：每年 30 或 24.5 天",
	"Example: Sunday 2 h → 2.0 h @ 100%%" : "示例：周日 2 小时 → 2.0 小时 @ 100%%",
	"Example: Sunday 2 h → 2.0 h @ __PCT__%%" : "示例：周日 2 小时 → 2.0 小时 @ __PCT__%%",
	"Example: hire 1 July + 3 months → usable until 30 September." : "示例：7 月 1 日入职 + 3 个月 → 可使用至 9 月 30 日。",
	"Example: tier 2:00 plus 8:00 actual work books 10:00." : "示例：档位 2:00 加实际工作 8:00，记 10:00。",
	"Example: tier 9:00 always books 9:00, no matter the actual work." : "示例：档位 9:00 始终记 9:00，与实际工作无关。",
	"Example: tier 9:00 with 10:00 actual work books only 9:00." : "示例：档位 9:00、实际工作 10:00，只记 9:00。",
	"Example: tier 9:00 with 7:00 actual work books 9:00 — a 2:00 top-up." : "示例：档位 9:00、实际工作 7:00，记 9:00——补足 2:00。",
	"Example: turn on Sunday to see a sample." : "示例：开启周日可查看样例。",
