	"Finish the open steps above — then you can stop new legacy requests." : "完成上方未完成步骤——然后即可停止新的旧版申请。",
	"Finish the paused session on the dashboard, or contact your administrator." : "在仪表板完成暂停的记录，或联系管理员。",
	"Finish tour" : "结束导览",
	"First" : "第一条",
	"First choose a sealed month, then download the official revision PDF for each person in your scope." : "先选择已封存月份，再为权限范围内每个人下载官方审计 PDF。",
	"First choose the scope above, then pick the type of report." : "先在上方选择范围，再选择报表类型。",
	"First day" : "第一天",
	"First day away" : "请假首日",
	"First day of employment. Vacation for the year of hire is prorated from this date." : "入职首日。入职当年的年假自此日期按比例计算。",
	"First pick the country whose working time law applies, then the default region for public holidays." : "先选择适用工时法的国家\/地区，再选择法定假日默认地区。",
	"Fixed value per person" : "每人固定值",
	"Fixed — always exactly this amount" : "固定——始终恰好此数额",
	"Fixed?" : "固定？",
	"Flex policy quiet window end hour" : "弹性政策静默窗口结束小时",
	"Flex policy quiet window start hour" : "弹性政策静默窗口开始小时",
	"Flexible" : "弹性",
	"For a 38.5-hour week, use 7.7 hours per day (= 38.5 ÷ 5) so open day balances convert fairly. The default 8 under-converts those balances." : "每周 38.5 小时请用每天 7.7 小时（= 38.5 ÷ 5），未结天数余额才能公平换算。默认 8 会少算这些余额。",
	"For a vacation that has not started yet, please cancel it and submit a sick leave request instead." : "尚未开始的年假，请取消后改提交病假申请。",
	"For an absence that has not started yet, please cancel it and submit a sick leave request instead." : "尚未开始的请假，请取消后改提交病假申请。",
	"For approved absences, an email with an iCal attachment (.ics) can be sent automatically." : "已批准的请假可自动发送带 iCal 附件（.ics）的邮件。",
	"For clocked entries less than %d days old: use Edit to change times, or Delete to remove the entry entirely. Older clocked entries: use Request correction. Entries in a finalized month or approved by your manager cannot be deleted here." : "%d 天内的打卡记录：用“编辑”改时间，或用“删除”移除整条。更早的打卡记录：用“申请更正”。已结算月份或主管已批准的记录不能在此删除。",
	"For non-shift models (flex policy), automatic clock-out is suppressed inside this daytime window. Shift work remains strict." : "非轮班模式（弹性政策）在此时段内抑制自动签退。轮班工作保持严格。",
	"For organization scope, download is available for working time export after preview." : "组织范围的工时导出在预览后可下载。",
	"For payroll (DATEV) files, open Administration → Global settings and use the «Exports and reporting» section with your date range. This page offers CSV and JSON only." : "工资（DATEV）文件请打开 管理 → 全局设置，使用“导出与报表”区块并选择日期范围。本页仅提供 CSV 和 JSON。",
	"For security and performance, entries load only when you click Show with a valid date range." : "为安全和性能考虑，只有在设置有效日期范围并点击“显示”后才加载记录。",
	"For security and performance, results are only loaded after both start and end date are set." : "为安全和性能考虑，只有在开始和结束日期都设置后才加载结果。",
	"For the selected absence types, a substitute must be designated." : "所选的请假类型必须指定代班人。",
	"For whom?" : "为谁？",
	"Forgot to clock out? Request a correction" : "忘记签退？申请更正",
	"Forgot to clock out? Request a retroactive clock-out for manager approval from your time entries list." : "忘记签退？在工时列表中申请补录签退，由主管批准。",
	"Form actions" : "表单操作",
	"Form initialization failed. Please refresh the page." : "表单初始化失败。请刷新页面。",
	"Format: AZC2 followed by a signed payload. One key per organisation." : "格式：AZC2 加签名载荷。每个组织一个密钥。",
	"Format: dd.mm.yyyy" : "格式：dd.mm.yyyy",
	"Formula: 30 × (work days per week ÷ 5)." : "公式：30 ×（每周工作日 ÷ 5）。",
	"Four decisions: name, amount, recipients, start date. The linked absence type is created automatically." : "四项决定：名称、数额、适用对象、开始日期。关联的请假类型会自动创建。",
