	"Full day or half day for this date. Morning or afternoon is not tracked." : "该日期的全天或半天。不区分上午或下午。",
	"Full months (Zwölftelung, German default)" : "整月计（Zwölftelung，德国默认）",
	"Full months (Zwölftelung, common DE default)" : "整月计（Zwölftelung，德国常用默认）",
	"Full months: each calendar month touched by the employment counts as 1\/12 of the annual entitlement; a fraction of half a day or more is rounded up to a full day (BUrlG §5). Exact days: annual entitlement times worked days divided by days in the year. This is not legal advice — consult HR for your collective agreement." : "整月计：在职期间涉及的每个日历月计为年度额度的 1\/12；半天及以上向上取整为一整天（BUrlG §5）。精确天数：年度额度 × 在职天数 ÷ 全年天数。这不是法律意见——集体协议请咨询人事。",
