	"Generate one calendar subscription link per scope. The feed contains approved absences only and never includes free-text reasons." : "每个范围生成一个日历订阅链接。订阅只含已批准请假，绝不包含自由文本原因。",
	"Generate one calendar subscription link per team and manager scope. The feed contains approved absences only and never includes free-text reasons." : "每个团队和主管范围生成一个日历订阅链接。订阅只含已批准请假，绝不包含自由文本原因。",
