	"German Labor Law Compliant" : "符合德国劳动法",
	"German labor law (ArbZG) allows a maximum of 10 hours per day. You have entered {hours} hours." : "德国劳动法（ArbZG）允许每天最多 10 小时。您输入了 {hours} 小时。",
	"German labor law (ArbZG) requires:" : "德国劳动法（ArbZG）要求：",
	"German labor law compliance" : "德国劳动法合规",
	"German labor law compliant time tracking for Nextcloud" : "适用于 Nextcloud 的德国劳动法合规工时跟踪",
	"German labor law requires at least 30 minutes break after 6 hours of work. You have only {minutes} minutes." : "德国劳动法要求工作 6 小时后至少休息 30 分钟。您只有 {minutes} 分钟。",
	"German labor law requires at least 45 minutes break after 9 hours of work. You have only {minutes} minutes." : "德国劳动法要求工作 9 小时后至少休息 45 分钟。您只有 {minutes} 分钟。",
	"German law: 30 min break from 6 h work, 45 min from 9 h. Enable automatic breaks or add times yourself." : "德国法律：工作满 6 小时休 30 分钟，满 9 小时休 45 分钟。请启用自动休息或自行添加时间。",
	"Germany" : "德国",
	"Gesamtzahl der Mitarbeitenden mit Zugriff auf die Zeiterfassung" : "有工时跟踪权限的员工总数",
