	"Get Started" : "开始使用",
	"Get a notification when it's time to take a required break. For example, after 5.5 hours you'll get a reminder to take at least a 15-minute break (ArG)." : "到该休息的时间时收到通知。例如工作 5.5 小时后提醒您至少休息 15 分钟（ArG）。",
	"Get a notification when it's time to take a required break. For example, after more than 6 hours you'll get a reminder to take at least a 30-minute break (AZG)." : "到该休息的时间时收到通知。例如工作超过 6 小时后提醒您至少休息 30 分钟（AZG）。",
	"Get a notification when it's time to take a required break. For example, if you work more than 6 hours, you'll get a reminder to take at least a 30-minute break." : "到该休息的时间时收到通知。例如工作超过 6 小时，提醒您至少休息 30 分钟。",
