	"Hour premiums are turned off for this organisation." : "贵组织已关闭工时津贴。",
	"Hours" : "小时",
	"Hours & rest" : "工时与休息",
	"Hours Today" : "今日工时",
	"Hours above the bank cap — eligible for payout at month end" : "超出账户上限的工时——月末可支付",
	"Hours and minutes (5h 30)" : "小时与分钟（5h 30）",
	"Hours at a glance" : "工时一览",
	"Hours delta" : "小时增减量",
	"Hours delta must be a number (use negative to reduce the balance)." : "小时增减量须为数字（用负数减少余额）。",
	"Hours display" : "工时显示",
	"Hours for this request use the organisation conversion factor until your administrator assigns a working-time model. Ask them to set your schedule so shorter Fridays and weekday nets apply correctly." : "在管理员分配工时模式前，此申请的工时按组织换算系数计算。请让他们设置您的计划，使较短的周五和周日净工时正确应用。",
	"Hours must be between 0.01 and 24" : "工时须在 0.01 至 24 之间",
	"Hours of rest between end of work and next start. DACH labour laws (ArbZG, AZG, ArG) generally require at least 11 hours." : "下班与下次上班之间的休息小时数。DACH 劳动法（ArbZG、AZG、ArG）一般要求至少 11 小时。",
	"Hours of rest between end of work and next start. German law requires at least 11 hours." : "下班与下次上班之间的休息小时数。德国法律要求至少 11 小时。",
	"Hours paid" : "已支付小时",
	"Hours per day (for conversion)" : "每天小时数（用于换算）",
	"Hours per day must be between 0.25 and 24." : "每天小时数须在 0.25 至 24 之间。",
	"Hours with a percentage for payroll handoff — not Saldo and not pay." : "按百分比折算的工时，用于工资交接——不是余额也不是薪酬。",
	"Hours with a percentage for reporting — not pay, and not your Saldo above." : "按百分比折算的工时，用于报表——不是薪酬，也不是上方余额。",
	"Hours with a percentage for reporting — not pay, and not your overtime Saldo." : "按百分比折算的工时，用于报表——不是薪酬，也不是您的加班余额。",
	"How Long to Keep Time Records" : "工时记录保留多久",
	"How Serious" : "严重程度",
	"How approved absences affect the flextime balance. Leave rules are on by default so vacation never creates minus hours; the sick-leave credit stays opt-in." : "已批准请假如何影响弹性工时余额。休假规则默认开启，年假不会产生负工时；病假计入仍为可选。",
	"How carryover works" : "结转如何运作",
	"How each time kind counts" : "各时间类型如何计入",
	"How is this calculated?" : "这是如何计算的？",
	"How it works" : "工作原理",
	"How long time records are kept before cleanup." : "工时记录在清理前保留多久。",
	"How many hours of rest someone must have between the end of one work day and the start of the next. German law requires at least 11 hours. Example: If someone finishes work at 6 PM, they cannot start again before 5 AM the next day." : "一天工作结束到次日开始之间必须休息的小时数。德国法律要求至少 11 小时。示例：某人下午 6 点下班，次日早上 5 点前不能再上班。",
	"How many hours you normally work each day. Decimal values are allowed (e.g. 7.74 for a 38.7 h week spread over five days)." : "您通常每天工作多少小时。允许小数（如每周 38.7 小时分摊到五天为 7.74）。",
	"How many months after each hire anniversary leftover vacation stays usable." : "每个入职周年后剩余年假仍可使用的月数。",
	"How many vacation days you get each year. In Germany, the standard is 25 days. Example: Enter 25 if you get 25 vacation days per year." : "您每年有多少年假。德国标准为 25 天。示例：每年 25 天年假就输入 25。",
	"How many years to keep time tracking records before they are automatically deleted. German law typically requires keeping records for 2 years. Example: Enter 2 to keep records for 2 years." : "工时记录在自动删除前保留多少年。德国法律一般要求保留 2 年。示例：输入 2 表示保留 2 年。",
	"How old a stamp may be when the phone or kiosk uploads it after an outage. Longer windows help over weekends; they also leave more room for wrong device clocks. 24 hours is the safe default." : "断网后手机或自助终端上传打卡的最长时限。更长的窗口便于跨周末补传，但也给错误的设备时钟留了更多余地。24 小时是安全的默认值。",
	"How payout works" : "支付如何运作",
	"How should annual vacation be calculated?" : "年假应如何计算？",
	"How the app calculates your breaks, and your assigned schedule." : "应用如何计算您的休息，以及分配给您的计划。",
	"How the credit applies" : "计入如何应用",
	"How the system checked each layer" : "系统如何逐层检查",
	"How this balance is calculated" : "此余额如何计算",
