	"How vacation days are calculated" : "年假天数如何计算",
	"How vacation entitlement is resolved" : "年假额度如何解析",
	"How well the rules are followed:" : "规则遵守情况：",
	"How well you follow the rules:" : "您的规则遵守情况：",
	"How working time totals are shown in the app. Decimal stays the default; choose hours and minutes if you prefer clock-style durations." : "应用中工时合计的显示方式。默认为小数；喜欢钟表式时长可选小时和分钟。",
	"How your request is approved" : "您的申请如何被批准",
	"How your vacation entitlement is calculated" : "您的年假额度如何计算",
	"Hypothetical team" : "假设团队",
	"Hypothetical team membership" : "假设团队成员关系",
	"Hypothetical team selection cleared." : "假设团队选择已清除。",
	"I drove myself" : "我自行驾驶",
	"I returned early" : "我提前返回",
	"I understand people without a hire date get no vacation until a start date is set" : "我理解未设入职日期的人在设置前没有年假",
	"I understand that older app versions cannot write custom location codes." : "我理解旧版应用无法写入自定义地点代码。",
	"I understand the effect and the rollback path." : "我理解其影响和回滚路径。",
	"I understand these rules never exceed the statutory minimum and save them anyway." : "我理解这些规则不会低于法定最低要求，仍要保存。",
	"I understand this action cannot be undone" : "我理解此操作无法撤销",
