	"I worked during the trip" : "旅途中我在工作",
	"Identifier (optional)" : "标识符（可选）",
	"Identify this rule set" : "标识此规则集",
	"If a break is left open for too long, the system automatically clocks out to prevent permanent pause status." : "如果休息长时间未结束，系统会自动签退，防止永久暂停状态。",
	"If a calendar month was finalized by mistake or a correction is required, you can reopen it here as an administrator for the employee whose month should be opened again. Use the search field to select that person (their Nextcloud account). You must enter a reason; the audit log records your administrator action, the reason, and who the change applies to. Previous snapshot rows remain in the database for traceability." : "如果日历月被误结算或需要更正，管理员可在此为该员工重新打开该月。用搜索框选择此人（其 Nextcloud 账户）。必须填写原因；审计日志会记录您的管理员操作、原因和作用对象。之前的快照行保留在数据库中以便追溯。",
	"If enabled, users can still turn this reminder off in their personal settings. Reminders are sent only for expected workdays (not weekends, holidays, or approved absences)." : "启用后，用户仍可在个人设置中关闭此提醒。提醒仅在应工作日发送（不含周末、假日或已批准请假）。",
	"If enabled: managers are resolved from ArbeitszeitCheck teams defined below. If disabled: managers are resolved from shared Nextcloud groups (default behavior)." : "启用时：主管从下方定义的 ArbeitszeitCheck 团队解析。停用时：主管从共享 Nextcloud 群组解析（默认行为）。",
	"If set, opening carryover per user cannot exceed this many days (Tarifvertrag \/ company policy). Leave empty for no cap. Imports and admin edits are clamped to this value." : "设置后，每人的期初结转不能超过此天数（集体协议\/公司政策）。留空为无上限。导入和管理员编辑会被限制到此值。",
	"If set, opening carryover per user cannot exceed this many hours (Tarifvertrag \/ company policy). Leave empty for no cap. Imports and admin edits are clamped to this value." : "设置后，每人的期初结转不能超过此小时数（集体协议\/公司政策）。留空为无上限。导入和管理员编辑会被限制到此值。",
	"If set, this date is saved as the overtime “Stichtag” when the new account is created. Leave empty to configure later in ArbeitszeitCheck → Administration → Employees." : "设置后，该日期将在新账户创建时保存为加班“Stichtag”（起算日）。留空可稍后在 ArbeitszeitCheck → 管理 → 员工 中配置。",
	"If you believe this is a mistake, contact your ArbeitszeitCheck administrator." : "如您认为有误，请联系 ArbeitszeitCheck 管理员。",
	"If you manage more than one team, you can choose one here." : "如果您管理多个团队，可在此选择一个。",
	"If you need help at any time, check the documentation or contact your administrator." : "如需帮助，请随时查阅文档或联系管理员。",
	"If you need to generate reports, please contact your administrator or manager." : "如需生成报表，请联系您的管理员或主管。",
	"If you think the result is wrong, please contact your HR administrator." : "如您认为结果有误，请联系人事管理员。",
	"If you were sick during vacation, please shorten or cancel the vacation first, then submit a separate sick leave request." : "如果年假期间生病，请先缩短或取消年假，然后单独提交病假申请。",
	"Ignore holiday (weekday rules only)" : "忽略假日（仅按周日规则）",
	"Immaculate Conception" : "圣母无染原罪节",
	"Immediate email for each request" : "每条申请即时发送邮件",
	"Immediately" : "立即",
	"Impact preview failed" : "影响预览失败",
	"Impact preview unavailable." : "影响预览不可用。",
	"Import" : "导入",
	"Import configuration" : "导入配置",
