	"Import file is too large (max 1 MB)" : "导入文件过大（最大 1 MB）",
	"Import file is too large (max 1 MB)." : "导入文件过大（最大 1 MB）。",
	"Import preview" : "导入预览",
	"Important: This is best-effort email delivery, not a guaranteed real-time calendar sync. Delivery can be delayed or fail due to mail server\/network issues. Source of truth remains ArbeitszeitCheck." : "重要：这是尽力而为的邮件投递，不是保证的实时日历同步。因邮件服务器\/网络问题可能延迟或失败。数据权威来源始终是 ArbeitszeitCheck。",
	"In Thunderbird: delete the old subscribed calendar completely, then add the new link. Cached events can otherwise keep showing generic English titles." : "在 Thunderbird 中：先彻底删除旧的订阅日历，再添加新链接。否则缓存的事件可能继续显示通用的英文标题。",
	"In default mode, violations are shown but saving is still possible. In strict mode, violations prevent saving the time entry." : "默认模式下显示违规但仍可保存。严格模式下违规会阻止保存工时记录。",
	"In feed now" : "已在订阅中",
	"In the app guide: pick sign-in methods, set a secret admin PIN, and choose NFC or an external RFID reader." : "在应用引导中：选择登录方式、设置管理员 PIN、选择 NFC 或外接 RFID 读卡器。",
	"In this what-if scenario, the employee would receive {days} vacation days per year, determined by the {layer}." : "在此假设情景中，该员工每年将获得 {days} 个年假日，由 {layer} 决定。",
	"In this what-if scenario, the employee would receive {days} vacation hours per year, determined by the {layer}." : "在此假设情景中，该员工每年将获得 {days} 个年假小时，由 {layer} 决定。",
