	"Minimum %1$d-hour rest period required between shifts (%2$s). Your last shift ended on %3$s at %4$s. You can clock in after %5$s (in %6$.1f hours). For a short break in the same session, use Pause instead of clocking out. Morning and afternoon blocks on the same calendar day (split shift) are allowed when the previous block did not run overnight." : "班次之间须至少休息 %1$d 小时（%2$s）。您上一班于 %3$s %4$s 结束。您可在 %5$s 后签到（还需 %6$.1f 小时）。同一记录中的短暂休息请用“暂停”而非签退。上一时段未跨夜时，允许同一日历日的上午\/下午分段班。",
