	"November" : "11月",
	"Number of calendar days after the last day of each month for employees to finalize manually. If the month is still open after that, a daily job seals it automatically (same snapshot as manual finalize). Pending time entry or absence approvals block auto-finalization. Use 0 to disable automatic sealing." : "每月最后一天后，留给员工手动结算的日历天数。此后仍未结算的月份由每日任务自动封存（与手动结算相同的快照）。待处理的工时或请假审批会阻止自动结算。设为 0 禁用自动封存。",
