	"Off" : "关",
	"Off by default. Only enable if your collective agreement allows transferring unused annual leave; consult HR \/ legal. When on, unused annual days for the year may be added to the next year’s carryover opening, subject to the maximum carryover cap above." : "默认关闭。仅当您的集体协议允许结转未用年假时才启用；请咨询人事\/法务。开启后，当年未用的年度天数可加入下一年结经期初，受上方最大结转上限限制。",
	"Off by default. Only enable if your collective agreement allows transferring unused annual leave; consult HR \/ legal. When on, unused annual hours for the year may be added to the next year’s carryover opening, subject to the maximum carryover cap above." : "默认关闭。仅当您的集体协议允许结转未用年假时才启用；请咨询人事\/法务。开启后，当年未用的年度小时可加入下一年结经期初，受上方最大结转上限限制。",
