	"Open shows ArbeitszeitCheck in the menu for everyone. Restricted hides it unless the person is allow-listed. System and delegated app administrators always pass the door. Employee and manager roles still apply after the door." : "“开放”在菜单中对所有人显示 ArbeitszeitCheck。“受限”则隐藏，除非此人在白名单中。系统和委派的应用管理员始终可通过。员工和主管角色在进入后仍然适用。",
