	"Open-source care on GitHub stays free" : "GitHub 上的开源关怀保持免费",
	"Opening balance at year start: %s" : "年初期初余额：%s",
	"Opening balance hours must be a number between -9999 and 9999." : "期初余额小时数须为 -9999 至 9999 之间的数字。",
	"Opening balance hours must be between -9999 and 9999" : "期初余额小时数须在 -9999 至 9999 之间",
	"Opening balance of carryover days for the selected calendar year (Resturlaub), e.g. from HR or migration. This is not the annual vacation entitlement from the working time model. The last day carryover can be used is set globally in Admin settings." : "所选日历年的结转天期初余额（Resturlaub），如来自人事或迁移。这不是工时模式的年度年假额度。结转可使用的最后一天在管理设置中全局设定。",
	"Opening balance year must be a four-digit year (e.g. 2026)." : "期初余额年份须为四位年份（如 2026）。",
	"Opening balance year must be between 2000 and 2100" : "期初余额年份须在 2000 至 2100 之间",
	"Opening balance year must be between 2000 and 2100." : "期初余额年份须在 2000 至 2100 之间。",
	"Opening overtime balance (hours)" : "加班期初余额（小时）",
	"Opens the time entry form with this day prefilled. Breaks and compliance checks stay the same as under Time entries." : "打开已预填该日期的工时记录表单。休息和合规检查与“工时记录”下相同。",
	"Operation completed successfully" : "操作已成功完成",
	"Operations" : "运营",
	"Optional" : "可选",
	"Optional Entgeltausfall \/ Ausfallprinzip for the flextime balance. Off by default so existing balances stay unchanged." : "弹性工时余额的可选 Entgeltausfall \/ Ausfallprinzip（缺勤抵扣原则）。默认关闭，现有余额不受影响。",
	"Optional description for this time entry" : "此工时记录的可选描述",
	"Optional description or notes about this work period" : "此工作时段的可选描述或备注",
	"Optional link from time entries to ProjectCheck projects." : "工时记录到 ProjectCheck 项目的可选关联。",
	"Optional notes for your manager" : "给主管的可选备注",
	"Optional reason for declining (leave empty for none):" : "可选的婉拒原因（留空则无）：",
	"Optional reason for rejection (leave empty for none):" : "可选的拒绝原因（留空则无）：",
	"Optional reason or notes for your absence request" : "请假申请的可选原因或备注",
	"Optional region or labor jurisdiction this set applies to." : "此规则集可选适用的地区或劳动司法辖区。",
	"Optional time windows for breaks, in timezone %s." : "可选的休息时段，时区 %s。",
	"Optional. Leave empty if the rule set is open-ended." : "可选。规则集无限期则留空。",
	"Optional. Leave empty to skip that premium in DATEV export." : "可选。留空则在 DATEV 导出中跳过该津贴。",
	"Optional. Link these hours to a ProjectCheck project, or leave “No project”." : "可选。将这些工时关联到 ProjectCheck 项目，或保留“无项目”。",
	"Optional. Use this for cross-border employees whose working time rules should differ from the organisation country. Leave empty to follow the organisation setting." : "可选。用于工时规则与组织国家不同的跨境员工。留空则遵循组织设置。",
	"Optional: Add notes or details about this work period (e.g., project work, meetings, tasks)" : "可选：添加此工作时段的备注或详情（如项目工作、会议、任务）",
	"Optional: Record your break times. Breaks of at least 15 minutes count toward legal requirements (ArbZG §4)." : "可选：记录您的休息时间。至少 15 分钟的休息才计入法定要求（ArbZG §4）。",
	"Optional: Record your break times. Breaks of at least 15 minutes count toward legal requirements (ArbZG §4). You can add multiple breaks." : "可选：记录您的休息时间。至少 15 分钟的休息才计入法定要求（ArbZG §4）。可添加多段休息。",
	"Optional: Record your break times. German law requires breaks for work over 6 hours: 30 minutes for 6-9 hours, 45 minutes for 9+ hours. Shorter shifts have no break requirements. Automatic breaks are added when needed for compliance. You can add additional manual breaks." : "可选：记录您的休息时间。德国法律要求工作超 6 小时须休息：6-9 小时休 30 分钟，9 小时以上休 45 分钟。更短的班次无休息要求。合规需要时会自动添加休息。您也可添加额外的手动休息。",
	"Optional: When did your break end?" : "可选：您的休息何时结束？",
	"Optional: When did your break end? Use automatic breaks for legal compliance." : "可选：您的休息何时结束？建议使用自动休息确保合规。",
	"Optional: When did your break start?" : "可选：您的休息何时开始？",
	"Optional: When did your break start? Use automatic breaks for legal compliance." : "可选：您的休息何时开始？建议使用自动休息确保合规。",
	"Optional: filter by Nextcloud user ID. Maximum date range: %d days. Times use your personal timezone." : "可选：按 Nextcloud 用户 ID 筛选。最大日期范围：%d 天。时间使用您的个人时区。",
	"Optional: link this stamp session to one ProjectCheck customer project for billing. ArbeitszeitCheck tracks attendance (one active session). To split the day across several projects, keep stamping here and log project hours in ProjectCheck — or ask your administrator. Leave “No project” to track time only. Projects with per-person pricing only appear if you are on the project team." : "可选：将此打卡记录关联到一个 ProjectCheck 客户项目用于计费。ArbeitszeitCheck 跟踪出勤（一个活跃记录）。要把一天拆到多个项目，请继续在此打卡并在 ProjectCheck 中登记项目工时——或咨询管理员。保留“无项目”则仅跟踪工时。按人计价的项目只有您是项目团队成员才显示。",
	"Optional: set the overtime start date (Stichtag) and an opening balance for a calendar year." : "可选：设置加班起算日（Stichtag）和某日历年的期初余额。",
	"Optional: set the overtime start date (Stichtag) and an opening balance for a calendar year. Use adjustments below to book payouts or period Nullung without changing recorded working time." : "可选：设置加班起算日（Stichtag）和某日历年的期初余额。用下方调整记录支付或周期清零，而不改变已记录的工时。",
	"Optionally choose a colleague who will cover your tasks during your absence." : "可选择一位在您请假期间代班的同事。",
	"Optionally let employees link working time to ProjectCheck projects." : "可让员工将工时关联到 ProjectCheck 项目。",
	"Optionally select a specific user. Leave empty to include all users." : "可选择特定用户。留空则包含所有用户。",
	"Or type end time as HH:MM" : "或输入 HH:MM 格式的结束时间",
	"Or type start time as HH:MM" : "或输入 HH:MM 格式的开始时间",
