	"To change tablet settings later: press and hold the large title at the top of the home screen for 5 seconds, then enter the admin PIN. There is no public Setup button." : "以后更改平板设置：长按主屏幕顶部大标题 5 秒，然后输入管理员 PIN。没有公开的设置按钮。",
