	"Total vacation hours for the whole request (not per day). Full range uses the employee’s work model (schedule), not a fixed 8 hours." : "整个申请的年假总小时数（不是每天）。整段范围按员工的工作模式（计划）计算，不是固定 8 小时。",
	"Total vacation hours for the whole request (not per day). “Full range” and “1 full day” use your work model (e.g. shorter Friday), not a fixed 8 hours. Public holidays reduce the final debit." : "整个申请的年假总小时数（不是每天）。“整段范围”和“1 整天”按您的工作模式（如较短的周五）计算，不是固定 8 小时。法定假日会减少最终扣减。",
	"Total: %1$d, Working: %2$d, Break: %3$d, Paused: %4$d, Clocked out: %5$d" : "共：%1$d，工作：%2$d，休息：%3$d，暂停：%4$d，已签退：%5$d",
	"Total:%1$d, Working:%2$d, Break:%3$d, Paused:%4$d, Clocked out:%5$d. Absent:%6$d (Vacation:%7$d, Sick:%8$d, Other:%9$d)." : "共：%1$d，工作：%2$d，休息：%3$d，暂停：%4$d，已签退：%5$d。缺席：%6$d（年假：%7$d，病假：%8$d，其他：%9$d）。",
	"Totals cover up to %1$d accounts (%2$d in the directory). Open Employees for the full list." : "合计覆盖最多 %1$d 个账户（目录中共 %2$d 个）。打开“员工”查看完整列表。",
	"Trace v" : "追踪 v",
	"Track work hours, manage absences, and ensure legal compliance." : "跟踪工时、管理请假并确保法律合规。",
