	"Trip review" : "出差审核",
	"Trips waiting for your review. Open one to see the recorded times, the rule result, and what will be booked." : "等待您审核的出差。打开一条可查看记录时间、规则结果和将入账的内容。",
	"Trust-Based" : "信任制",
	"Trust-based" : "信任制",
	"Try a wider date range or a different status, or clear the filter to see all entries again." : "试试更大的日期范围或换个状态，或清除筛选以重新显示全部记录。",
	"Try a wider date range, another work location, or a different status, or clear the filter to see all entries again." : "试试更大的日期范围、其他工作地点或换个状态，或清除筛选以重新显示全部记录。",
	"Try again" : "重试",
	"Try out: how many vacation days does an employee actually get on a given date? See exactly which layer was applied and why." : "试一试：某员工在某天实际有多少年假日？精确查看应用了哪一层级以及原因。",
	"Try out: how many vacation hours does an employee actually get on a given date? See exactly which layer was applied and why." : "试一试：某员工在某天实际有多少年假小时？精确查看应用了哪一层级以及原因。",
	"Tue" : "周二",
	"Tuesday" : "星期二",
	"Turn foyer tablet clocking on or off. Needs a Terminal license and at least one paired tablet." : "开关门厅平板打卡。需要终端许可证和至少一台已配对平板。",
	"Turn off manual entries if everyone must use the punch clock only." : "如果所有人都只能用打卡钟，请关闭手动记录。",
	"Turn off only if you want to enter every break manually." : "仅当您想手动输入每段休息时才关闭。",
	"Turn off stamping if your organisation records hours only via manual entries — the punch clock disappears for all employees." : "如果贵组织只通过手动记录登记工时，请关闭打卡——打卡钟将对所有员工隐藏。",
	"Turn on hour premiums" : "开启工时津贴",
	"Turn on the business-trip feature" : "开启出差功能",
	"Turn on time-account credit postings" : "开启工时账户计入",
	"Turn on “Allow kiosk access” for this person, then continue with step 3." : "为此人开启“允许自助终端访问”，然后继续第 3 步。",
	"Turning this off hides the project picker everywhere and stops you from linking new hours to a project. Projects you already linked stay linked until a manager changes them. Projects with per-person pricing only appear if you are on the project team." : "关闭后会在各处隐藏项目选择器，并阻止您将新工时关联到项目。已关联的项目保持关联，直到主管更改。按人计价的项目只有您是项目团队成员才显示。",
	"Type" : "类型",
	"Type %s to confirm" : "输入 %s 以确认",
	"Type REPLACE to confirm" : "输入 REPLACE 确认",
	"Type REPLACE to confirm." : "输入 REPLACE 确认。",
	"Type a name or email address to find employees quickly" : "输入姓名或邮箱以快速查找员工",
	"Type an employee name to find employees quickly" : "输入员工姓名以快速查找",
	"Type and status" : "类型与状态",
	"Type at least 2 characters to search for a person." : "输入至少 2 个字符以搜索人员。",
	"Type at least 2 characters to search managers for the selected team." : "输入至少 2 个字符以搜索所选团队的主管。",
	"Type at least 2 characters to search." : "输入至少 2 个字符以搜索。",
	"Type at least 2 characters to search. Leave empty to browse the list page by page." : "输入至少 2 个字符进行搜索。留空则逐页浏览列表。",
	"Type at least 2 characters, then choose an employee. Leave empty to include everyone in your scope." : "输入至少 2 个字符，然后选择员工。留空则包含权限范围内所有人。",
	"Type at least 2 characters, then choose the employee." : "输入至少 2 个字符，然后选择员工。",
	"Type at least 2 characters, then select the employee whose finalized month you are reopening." : "输入至少 2 个字符，然后选择要重新打开其已结算月份的员工。",
	"Type at least 2 characters. Leave empty to browse page by page." : "输入至少 2 个字符。留空则逐页浏览。",
	"Type at least 2 letters of the name or login, then pick the person from the list." : "输入姓名或登录名的至少 2 个字符，然后从列表中选择。",
	"Type at least 2 letters of the name or user ID, then pick the person from the list." : "输入姓名或用户 ID 的至少 2 个字符，然后从列表中选择。",
	"Type at least two characters, then select a person from the list." : "输入至少两个字符，然后从列表中选择人员。",
	"Type at least two characters, tick several people, then assign them together." : "输入至少两个字符，勾选多人，然后一起分配。",
	"Type the hour and minute, or open the clock to pick a time. Example: 09:00." : "输入小时和分钟，或打开时钟选择时间。示例：09:00。",
	"Type to filter, then pick the employee whose finalized month you are reopening (their account)." : "输入以筛选，然后选择要重新打开其已结算月份的员工（其账户）。",
	"Type to search" : "输入以搜索",
	"Type to search for an employee" : "输入以搜索员工",
	"Type to search for people" : "输入以搜索人员",
	"Type, start date, and end date are required" : "需要类型、开始日期和结束日期",
	"Type, start_date, and end_date are required" : "需要 type、start_date 和 end_date",
	"Type: %1$s" : "类型：%1$s",
	"Typical number of work days each week for this model (e.g. 4 for a four-day week). Used for model-based vacation entitlement calculations." : "此模式每周典型工作天数（如四天工作周为 4）。用于按模式的年假额度计算。",
	"Typical value in Germany: 31 March (month 3, day 31). If that day does not exist in a month (e.g. 31 February), the last day of that month is used automatically." : "德国典型值：3 月 31 日（月 3，日 31）。若该月不存在此日（如 2 月 31 日），自动用该月最后一天。",
	"UE" : "UE",
	"Unable to load compliance data." : "无法加载合规数据。",
	"Unable to load overtime alerts." : "无法加载加班提醒。",
	"Unauthorized" : "未授权",
	"Unclassified travel time blocks submission" : "未分类的差旅时间阻止提交",
	"Under GDPR, you have the right to access your personal data. You can export all your time tracking data at any time." : "根据 GDPR，您有权访问您的个人数据。您可随时导出全部工时跟踪数据。",
	"Under the GDPR you can request a copy of your data, correction of inaccuracies or deletion of your records. ArbeitszeitCheck provides a self-service data export and deletion request inside the app under \"My settings\" → \"Data and privacy\"." : "根据 GDPR，您可请求获取数据副本、更正不准确之处或删除记录。ArbeitszeitCheck 在应用内“我的设置”→“数据与隐私”下提供自助数据导出和删除请求。",
