	"Unresolved users \/ groups" : "无法解析的用户\/组",
	"Unresolved violations: %s. Open compliance violations." : "未解决违规：%s。打开合规违规。",
	"Unsaved changes" : "未保存的更改",
	"Up to" : "最多",
	"Up to 1 employee may be re-resolved by this change." : "此更改最多可能重新解析 1 名员工。",
	"Up to 5 digits." : "最多 5 位。",
	"Up to 7 digits. Saved with Save on this page." : "最多 7 位。随本页“保存”保存。",
	"Up to 7 digits. Saved with “Save all settings”." : "最多 7 位。随“保存所有设置”保存。",
	"Up to 8 digits. Required for DATEV export of this employee." : "最多 8 位。此员工 DATEV 导出必填。",
	"Up to two decimal places are allowed, e.g. 1.5 or 4.25 — comma or dot both work." : "最多允许两位小数，如 1.5 或 4.25——逗号或点均可。",
	"Up to {n} employees may be re-resolved by this change." : "此更改最多可能重新解析 {n} 名员工。",
	"Update" : "更新",
	"Update Entry" : "更新记录",
	"Update Request" : "更新申请",
	"Update end date" : "更新结束日期",
	"Update end date and shorten absence" : "更新结束日期并缩短请假",
	"Update time entry" : "更新工时记录",
	"Updated" : "已更新",
	"Updated %1$d, failed %2$d." : "已更新 %1$d，失败 %2$d。",
	"Updates whenever your calendar app refreshes the subscription." : "每当您的日历应用刷新订阅时更新。",
	"Upper bound: counts users without an L1\/L2\/L3 override at all. Some users may still be served by a higher layer." : "上限：统计完全没有 L1\/L2\/L3 覆盖的用户。部分用户可能仍由更高层级覆盖。",
	"Upper limit of daily working time in hours. German labor law (ArbZG) allows 8 hours normally, up to 10 in special cases." : "每日工时上限（小时）。德国劳动法（ArbZG）通常允许 8 小时，特殊情况最多 10 小时。",
	"Upper limit of daily working time in hours. The suggested default comes from the selected country profile (Germany ArbZG: up to 10; Austria AZG: up to 12). Changing the country does not overwrite a value you already set." : "每日工时上限（小时）。建议默认值来自所选国家模板（德国 ArbZG：最多 10；奥地利 AZG：最多 12）。更改国家不会覆盖您已设置的值。",
	"Upper limit of daily working time in hours. The suggested default comes from the selected country profile (Germany ArbZG: up to 10; Austria AZG: up to 12; Switzerland ArG: up to 10). Changing the country does not overwrite a value you already set." : "每日工时上限（小时）。建议默认值来自所选国家模板（德国 ArbZG：最多 10；奥地利 AZG：最多 12；瑞士 ArG：最多 10）。更改国家不会覆盖您已设置的值。",
	"Uri" : "乌里州",
	"Use \"Start Break\" and \"End Break\" to record your breaks. The system will remind you if you forget." : "用“开始休息”和“结束休息”记录您的休息。忘记时系统会提醒您。",
	"Use 0–366 in steps of 0.5 (for example 25 or 25.5)." : "用 0–366，步进 0.5（如 25 或 25.5）。",
	"Use 7.7" : "用 7.7",
	"Use 7.7 (= 38.5 ÷ 5) so open day balances convert fairly." : "用 7.7（= 38.5 ÷ 5）使未结天数余额公平换算。",
	"Use ArbeitszeitCheck teams for approvals" : "审批使用 ArbeitszeitCheck 团队",
	"Use ArbeitszeitCheck teams instead of Nextcloud groups" : "用 ArbeitszeitCheck 团队代替 Nextcloud 群组",
	"Use a compact date range. The maximum window is 365 days and feeds above 5000 approved absences are rejected." : "使用紧凑的日期范围。最大窗口为 365 天，超过 5000 条已批准请假的订阅会被拒绝。",
	"Use app teams setting saved" : "“使用应用内团队”设置已保存",
	"Use fixed value, automatic from schedule, or tariff rule. Exception mode requires a reason." : "使用固定值、按计划自动或资费规则。例外模式需要原因。",
	"Use global default state" : "使用全局默认州",
	"Use organisation default" : "使用组织默认",
	"Use quick actions and role-based status sections in one place." : "在一处使用快捷操作和按角色的状态区块。",
	"Use suggested version" : "使用建议版本",
	"Use the \"Clock In\" button to start tracking your work time. When you finish, click \"Clock Out\" to stop." : "用“签到”按钮开始跟踪工时。结束时点击“签退”停止。",
	"Use the arrow keys to move between exports, then press Enter or Space to select." : "用方向键在导出项间移动，按回车或空格选择。",
	"Use the date picker — only ISO YYYY-MM-DD dates are accepted." : "使用日期选择器——只接受 ISO YYYY-MM-DD 日期。",
	"Use the same form for old vacation, sick leave, migration records, and future requests. Closed months stay protected and cannot be changed unless an administrator reopens them." : "旧的年假、病假、迁移记录和未来的申请都用同一表单。已封存月份保持受保护，除非管理员重新打开，否则不能更改。",
	"Use these buttons to track your working hours. Click \"Clock In\" when you start working and \"Clock Out\" when you finish." : "用这些按钮跟踪您的工时。开始工作时点“签到”，结束时点“签退”。",
	"Use these settings to prevent users from staying in an open break state for many hours by accident." : "用这些设置防止用户意外长时间停留在休息状态。",
	"Use this form to edit your time entry. The form will automatically check compliance with German labor law requirements." : "用此表单编辑您的工时记录。表单会自动检查是否符合德国劳动法要求。",
	"Use this form to record when you worked. Fill in the date, start time, end time, and optionally break times. The form will automatically check compliance with German labor law requirements." : "用此表单记录您的工作时间。填写日期、开始时间、结束时间，可选休息时间。表单会自动检查是否符合德国劳动法要求。",
	"Use this when the contract does not match any shared working time model. The weekly and daily hours below apply only to this employee." : "当合同不匹配任何共享工时模式时使用。下方的每周和每日工时仅适用于此员工。",
	"Use valid email addresses separated by commas. Duplicates are removed automatically." : "使用逗号分隔的有效邮箱。重复地址自动去重。",
	"Use “Rotate link” on an existing row to replace its URL. Calendar apps with the old link stop updating immediately." : "在现有行上用“轮换链接”替换其 URL。使用旧链接的日历应用立即停止更新。",
	"Used" : "已用",
	"Used for statutory holidays and compliance when no specific region is configured for employees or teams." : "员工或团队未配置特定地区时，用于法定假日和合规。",
	"Used for statutory holidays and compliance when no specific region is configured for employees." : "员工未配置特定地区时，用于法定假日和合规。",
	"Used for statutory holidays and compliance when no specific state is configured for employees or teams." : "员工或团队未配置特定州时，用于法定假日和合规。",
	"Used only when converting days ↔ hours. Day-to-day booking still follows each person’s work schedule." : "仅在天数 ↔ 小时换算时使用。日常预订仍按每人的工作计划。",
