	"Warning: 6-month average weekly working hours (%.2f h\/week) exceeds 48 hours\/week (ArbZG §3)." : "警告：6 个月平均每周工时（%.2f 小时\/周）超过 48 小时\/周（ArbZG §3）。",
	"Warning: 6-month average working hours (%.2f h\/day) exceeds 8 hours\/day. 10-hour days are only allowed if the average does not exceed 8 hours (ArbZG §3)." : "警告：6 个月平均工时（%.2f 小时\/天）超过 8 小时\/天。只有平均不超过 8 小时时才允许 10 小时工作日（ArbZG §3）。",
	"Warning: average weekly working hours over %1$d weeks (%2$.2f h\/week) exceed %3$d hours\/week (%4$s)." : "警告：%1$d 周平均每周工时（%2$.2f 小时\/周）超过 %3$d 小时\/周（%4$s）。",
	"Warning: average working hours over %1$d weeks (%2$.2f h\/day) exceed %3$d hours\/day. Longer days are only allowed if the average stays within the limit (%4$s)." : "警告：%1$d 周平均工时（%2$.2f 小时\/天）超过 %3$d 小时\/天。只有平均保持在上限内才允许更长工作日（%4$s）。",
	"Warning: employee list was truncated; contact support." : "警告：员工列表已被截断；请联系支持。",
	"Warning: more than one organisation default is active on the same date. Resolution falls back to the latest row and emits a degraded flag. Please remove the conflicting row." : "警告：同一日期有多个组织默认值生效。解析将回退到最新一行并发出降级标记。请移除冲突行。",
