	"When ProjectCheck is enabled, you can optionally link billing hours on a project the employee is allowed to use." : "启用 ProjectCheck 后，您可以选择将计费工时关联到员工可用的项目。",
	"When a colleague requests an absence and selects you as their substitute, you will see the request here." : "同事申请请假并选您为代班人时，您会在此看到请求。",
	"When a substitute is selected, emails can be sent at each step of the approval process." : "选择代班人后，审批流程的每一步都可发送邮件。",
	"When activated, the rule set will take effect at the chosen point in time." : "激活后，规则集将在所选时间点生效。",
	"When an absence is approved, the employee can receive an email with an iCalendar (.ics) attachment so they can add the absence to their calendar." : "请假批准时，员工可收到带 iCalendar（.ics）附件的邮件，以便把请假加入日历。",
	"When an employee joins or leaves during the year, the annual vacation entitlement is reduced to the part of the year actually worked. This only applies to employees who have an employment start and\/or end date set under Employees. Choose how the reduction is calculated." : "员工年中入职或离职时，年度年假额度按实际工作部分折算。这只适用于在“员工”下设置了入职和\/或离职日期的员工。请选择折算方式。",
	"When assigning working time models, the suggested default is %1$d vacation days per year for the selected country (Germany\/Austria typically 25; Switzerland typically 20). Existing assignments are never changed automatically." : "分配工时模式时，建议默认值为所选国家每年 %1$d 个年假日（德国\/奥地利通常 25；瑞士通常 20）。现有分配永远不会自动更改。",
