	"Working time rules are not affected — they follow the country configured for the whole organisation." : "工时规则不受影响——它们遵循整个组织配置的国家。",
	"Working time rules follow the Austrian Working Time Act (AZG) and Rest Act (ARG)." : "工时规则遵循奥地利工时法（AZG）和休息法（ARG）。",
